<?php require_once __DIR__.'/includes/functions.php';$number=preg_replace('/[^A-Z0-9-]/','',$_GET['order']??'');$title='تم استلام طلبكِ | ALAN';$stmt=db()->prepare('SELECT total FROM orders WHERE order_number=?');$stmt->execute([$number]);$order=$stmt->fetch();$total=$order?(float)$order['total']:0;include __DIR__.'/includes/header.php';?><div class="page empty"><p class="eyebrow">شكراً لاختياركِ الآن</p><h1>تم استلام طلبكِ بنجاح ✦</h1><p>رقم طلبكِ: <strong><?=e($number)?></strong><br>سنتصل بكِ قريباً لتأكيد الطلب قبل الشحن.</p><a class="btn" href="<?=base('track-order.php')?>">تتبّع الطلب</a></div><?php if(!isset($_SESSION['pixel_purchase_fired'][$number])): $_SESSION['pixel_purchase_fired'][$number]=true; ?><script>if(typeof fbq !== 'undefined') fbq('track', 'Purchase', {currency: 'DZD', value: <?=$total?>}, {eventID: '<?=e($number)?>'}); if(typeof ttq !== 'undefined') ttq.track('PlaceAnOrder', {currency: 'DZD', value: <?=$total?>, content_id: '<?=e($number)?>'});</script><?php endif; include __DIR__.'/includes/footer.php';?>
